using System.Security.Cryptography;
using System.Text.Json;
using DotReticulum.Core;
using DotReticulum.Interfaces;
using DotReticulum.Transport;
using LXMF;

namespace NomadNet.Tests;

// Public fixture generated by the actual primary constructor and router save APIs at
// f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2 with RNS a29bfb5 / LXMF e8ba024.
// Independently regenerated byte-identically on Windows/Linux. Git-blob SHA-256s are in the fixture.
[Trait("Category", "Integration")]
public sealed class NomadNetRouterProfileTests
{
    [Fact]
    public void ExecutedPrimaryFixtureRecordsClientLayoutAndPersistence()
    {
        using var fixture = Fixture();
        var root = fixture.RootElement;
        Assert.Equal("f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2", root.GetProperty("commit").GetString());
        Assert.Equal("1.5.7", root.GetProperty("rnsVersion").GetString());
        Assert.Equal("1.2.1", root.GetProperty("lxmfVersion").GetString());
        Assert.Equal("c36ce4c537fe5af534910d1f5200d2a2ea5dd50f74bf9e4157222eff15614eb2",
            root.GetProperty("sources").GetProperty("nomadnet/NomadNetworkApp.py").GetString());
        Assert.Equal("storage/lxmf", root.GetProperty("layout").GetString());
        Assert.Equal(5, root.GetProperty("clientFiles").GetArrayLength());
        Assert.True(root.GetProperty("nodeStatsWrittenByClient").GetBoolean());
        Assert.False(root.GetProperty("propagationNode").GetBoolean());
        Assert.True(root.GetProperty("ownRatchetsSignatureValid").GetBoolean());
        Assert.Equal(1, root.GetProperty("ownRatchetsCount").GetInt32());
        Assert.Equal(0, root.GetProperty("pendingInbound").GetInt32());
        Assert.Equal(0, root.GetProperty("pendingOutbound").GetInt32());
        Assert.Equal(9, root.GetProperty("stampCost").GetInt32());
    }

    [Fact]
    public async Task ImportsPublicReferenceStoresOwnIdentityRatchetsAndRestartsWithoutSubscribers()
    {
        using var profile = new Profile();
        var before = Snapshot(profile.Source);
        var report = await profile.ImportAsync();
        Assert.Equal(before, Snapshot(profile.Source));
        Assert.Empty(report.NotImportedFiles);
        Assert.Contains(report.Warnings, warning => warning.Contains("Client queues/links", StringComparison.Ordinal));
        var secret = await File.ReadAllBytesAsync(Path.Combine(profile.Target, "identity"));
        try
        {
            using var restored = Identity.FromPrivateKey(secret);
            Assert.Equal(profile.Own.HexHash, restored.HexHash);
        }
        finally { CryptographicOperations.ZeroMemory(secret); }
        await using var interfaces = new PacketInterfaceManager([]);
        await using var transport = new TransportRouter(interfaces);
        for (var restart = 0; restart < 2; restart++)
        {
            await using var router = new LxmRouter(transport, profile.Own, options: profile.Options);
            Assert.Equal(9, router.GetOutboundStampCost(Peer));
            Assert.True(router.HasMessage(Enumerable.Repeat((byte)0x33, 32).ToArray()));
            Assert.Equal(0, router.PendingOutbound);
            Assert.Null(router.MessageReceived);
            var outbound = Assert.IsType<LxmTicket>(router.Tickets.GetOutbound(Peer));
            try { Assert.Equal(Token, outbound.Token); }
            finally { CryptographicOperations.ZeroMemory(outbound.Token); }
            var inbound = router.Tickets.GetInbound(Peer);
            try { Assert.Equal(Token, Assert.Single(inbound)); }
            finally { foreach (var token in inbound) CryptographicOperations.ZeroMemory(token); }
            Assert.Null(router.Tickets.Generate(Peer));
        }
        var ratchets = File.ReadAllBytes(profile.NativeRatchets);
        try
        {
            var keys = SignedDestinationRatchetFile.Decode(profile.Own, ratchets);
            try { Assert.Equal(profile.RatchetHash, SHA256.HashData(Assert.Single(keys))); }
            finally { foreach (var key in keys) CryptographicOperations.ZeroMemory(key); }
        }
        finally { CryptographicOperations.ZeroMemory(ratchets); }
        if (!OperatingSystem.IsWindows())
            foreach (var path in Directory.GetFiles(Path.Combine(profile.Target, "storage", "lxmf"), "*", SearchOption.AllDirectories)
                .Where(path => !path.EndsWith(".lock", StringComparison.Ordinal)))
                Assert.Equal(UnixFileMode.UserRead | UnixFileMode.UserWrite, File.GetUnixFileMode(path));
    }

    [Fact]
    public async Task MalformedClientFilesFailAtomicallyWithoutRepairOrSecretReplacement()
    {
        var cases = new (string Name, byte[] Bytes)[]
        {
            ("available_tickets", [0xc1]),
            ("available_tickets", MsgPack.Pack(new Dictionary<object, object?> { ["outbound"] = new Dictionary<object, object?>() })),
            ("available_tickets", Tickets(outbound: new Dictionary<object, object?> { [Peer] = new object?[] { double.NaN, Token } })),
            ("available_tickets", Tickets(outbound: new Dictionary<object, object?> { [Peer] = new object?[] { 2100000000.0, new byte[15] } })),
            ("available_tickets", Tickets(inbound: new Dictionary<object, object?> { [Peer] = new Dictionary<object, object?> { [Token] = new object?[] { true } } })),
            ("outbound_stamp_costs", MsgPack.Pack(new Dictionary<object, object?> { [Peer] = new object?[] { 2000000000.0, 255L } })),
            ("outbound_stamp_costs", MsgPack.Pack(new Dictionary<object, object?> { [Peer] = new object?[] { "timestamp", 9L } })),
            ("local_deliveries", MsgPack.Pack(new Dictionary<object, object?> { [new byte[16]] = 2000000000.0 })),
            ("locally_processed", MsgPack.Pack(new Dictionary<object, object?> { [new byte[32]] = double.PositiveInfinity })),
            ("local_deliveries", MsgPack.Pack(new Dictionary<object, object?> { [new byte[32]] = true })),
        };
        foreach (var (name, bytes) in cases)
        {
            using var profile = new Profile();
            await File.WriteAllBytesAsync(Path.Combine(profile.RouterSource, name), bytes);
            var before = Snapshot(profile.Source);
            await Assert.ThrowsAsync<InvalidDataException>(() => profile.ImportAsync());
            Assert.Equal(before, Snapshot(profile.Source));
            profile.AssertNotPublished();
        }
        using var signed = new Profile();
        var envelope = File.ReadAllBytes(signed.SourceRatchets);
        envelope[^1] ^= 1;
        await File.WriteAllBytesAsync(signed.SourceRatchets, envelope);
        CryptographicOperations.ZeroMemory(envelope);
        await Assert.ThrowsAsync<InvalidDataException>(() => signed.ImportAsync());
        signed.AssertNotPublished();
    }

    [Fact]
    public async Task ByteEntryTicketAndOwnRatchetBoundsRejectRatherThanTruncate()
    {
        using var profile = new Profile();
        var destinations = new Dictionary<object, object?>();
        for (var index = 0; index < 4097; index++)
        {
            var key = new byte[16];
            System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(key, index);
            destinations[key] = new object?[] { 2100000000.0, Token };
        }
        var inbound = new Dictionary<object, object?>();
        for (byte index = 0; index < 17; index++) { var key = new byte[16]; key[0] = index; inbound[key] = new object?[] { 2100000000.0 }; }
        var history = new Dictionary<object, object?>();
        for (var index = 0; index < 65_537; index++)
        {
            var key = new byte[32];
            System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(key, index);
            history[key] = 2000000000.0;
        }
        foreach (var (name, bytes) in new[]
        {
            ("available_tickets", Tickets(outbound: destinations)),
            ("available_tickets", Tickets(inbound: new Dictionary<object, object?> { [Peer] = inbound })),
            ("local_deliveries", MsgPack.Pack(history)),
            ("available_tickets", new byte[4 * 1024 * 1024 + 1]),
            ("outbound_stamp_costs", new byte[8 * 1024 * 1024 + 1]),
        })
        {
            var path = Path.Combine(profile.RouterSource, name);
            var original = File.ReadAllBytes(path);
            await File.WriteAllBytesAsync(path, bytes);
            await Assert.ThrowsAnyAsync<Exception>(() => profile.ImportAsync());
            profile.AssertNotPublished();
            await File.WriteAllBytesAsync(path, original);
        }
        var keys = Enumerable.Range(0, 513).Select(_ => RandomNumberGenerator.GetBytes(32)).ToArray();
        var encoded = SignedDestinationRatchetFile.Encode(profile.Own, keys);
        try { await File.WriteAllBytesAsync(profile.SourceRatchets, encoded); }
        finally
        {
            CryptographicOperations.ZeroMemory(encoded);
            foreach (var key in keys) CryptographicOperations.ZeroMemory(key);
        }
        await Assert.ThrowsAsync<InvalidDataException>(() => profile.ImportAsync());
        profile.AssertNotPublished();
    }

    [Fact]
    public async Task CancellationAndLateFailureLeaveNoPublishedRouterStateAndRetrySucceeds()
    {
        using var profile = new Profile();
        using var canceled = new CancellationTokenSource();
        canceled.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => profile.ImportAsync(canceled.Token));
        profile.AssertNotPublished();
        var bad = Path.Combine(profile.Source, "storage", "conversations", new string('a', 32), new string('b', 64));
        Directory.CreateDirectory(Path.GetDirectoryName(bad)!);
        await File.WriteAllBytesAsync(bad, [0xc1]);
        var before = Snapshot(profile.Source);
        await Assert.ThrowsAnyAsync<Exception>(() => profile.ImportAsync());
        Assert.Equal(before, Snapshot(profile.Source));
        profile.AssertNotPublished();
        File.Delete(bad);
        using var cancellation = new CancellationTokenSource();
        using var watcher = new FileSystemWatcher(profile.Root, "native.profile-import-*")
        { NotifyFilter = NotifyFilters.DirectoryName };
        var observed = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        watcher.Created += (_, args) =>
        {
            cancellation.Cancel();
            observed.TrySetResult();
        };
        watcher.EnableRaisingEvents = true;
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => profile.ImportAsync(cancellation.Token));
        await observed.Task.WaitAsync(TimeSpan.FromSeconds(10));
        profile.AssertNotPublished();
        watcher.EnableRaisingEvents = false;
        await profile.ImportAsync();
        Assert.True(File.Exists(profile.NativeRatchets));
    }

    [Fact]
    public async Task MigratedDuplicatesSurviveRestartAndObserverFaultsDoNotDisableHealthyDelivery()
    {
        using var profile = new Profile();
        LxMessage Paper(string content)
        {
            var message = LxMessage.Create(LxMessage.DeliveryDestinationHash(profile.Own), profile.Own, content, method: LxmMethod.Paper);
            message.Pack(destinationIdentity: profile.Own);
            return message;
        }
        var old = Paper("historically delivered");
        await File.WriteAllBytesAsync(Path.Combine(profile.RouterSource, "local_deliveries"),
            MsgPack.Pack(new Dictionary<object, object?> { [old.Hash!] = 2000000000.0 }));
        await profile.ImportAsync();
        await using var interfaces = new PacketInterfaceManager([]);
        await using var transport = new TransportRouter(interfaces);
        for (var restart = 0; restart < 2; restart++)
        {
            await using var router = new LxmRouter(transport, profile.Own, options: profile.Options);
            Assert.Equal(LxmPaperIngestResult.Duplicate, await router.IngestPaperUriAsync(old.AsUri()));
            var fresh = Paper("healthy " + restart);
            var logs = new List<string>();
            router.Log = logs.Add;
            if (restart == 1)
            {
                var delivered = 0;
                router.MessageReceived = _ => throw new InvalidOperationException("synthetic failing observer");
                router.MessageReceived += _ => delivered++;
                Assert.Equal(LxmPaperIngestResult.LocalDelivery, await router.IngestPaperUriAsync(fresh.AsUri()));
                Assert.Equal(1, delivered);
                Assert.Contains(logs, line => line.Contains("receive observer failed", StringComparison.Ordinal));
            }
            else Assert.Equal(LxmPaperIngestResult.LocalDelivery, await router.IngestPaperUriAsync(fresh.AsUri()));
            Assert.True(router.HasMessage(fresh.Hash!));
        }
    }

    [Fact]
    public async Task OptionalClientFilesAndExcludedPropagationOrForeignFilesAreExplicit()
    {
        using var profile = new Profile();
        File.WriteAllBytes(Path.Combine(profile.RouterSource, "node_stats"), [0xc1]);
        File.WriteAllBytes(Path.Combine(profile.RouterSource, "peers"), [0xc1]);
        File.WriteAllBytes(Path.Combine(profile.RouterSource, "available_tickets.tmp.interrupted"), [0xc1]);
        File.WriteAllBytes(Path.Combine(profile.RouterSource, "ratchets", new string('f', 32) + ".ratchets"), [0xc1]);
        foreach (var file in Directory.GetFiles(profile.RouterSource)) if (Path.GetFileName(file) is not ("node_stats" or "peers" or "available_tickets.tmp.interrupted")) File.Delete(file);
        File.Delete(profile.SourceRatchets);
        var report = await profile.ImportAsync();
        Assert.Equal(4, report.NotImportedFiles.Count);
        Assert.False(Directory.Exists(Path.Combine(profile.Target, "storage", "lxmf")));
        Assert.Contains(report.Warnings, warning => warning.Contains("node_stats", StringComparison.Ordinal));
        await Assert.ThrowsAsync<IOException>(() => profile.ImportAsync());
    }

    private static byte[] Peer => Enumerable.Repeat((byte)0x11, 16).ToArray();
    private static byte[] Token => Enumerable.Repeat((byte)0x22, 16).ToArray();
    private static JsonDocument Fixture() => JsonDocument.Parse(typeof(NomadNetRouterProfileTests).Assembly
        .GetManifestResourceStream("NomadNet.Tests.NomadNetRouterProfileVectors.json")!);
    private static byte[] Tickets(Dictionary<object, object?>? outbound = null, Dictionary<object, object?>? inbound = null) =>
        MsgPack.Pack(new Dictionary<object, object?> { ["outbound"] = outbound ?? [], ["inbound"] = inbound ?? [],
            ["last_deliveries"] = new Dictionary<object, object?>() });
    private static string[] Snapshot(string root) => Directory.GetFiles(root, "*", SearchOption.AllDirectories)
        .Order(StringComparer.Ordinal).Select(path => Path.GetRelativePath(root, path) + ":" +
            Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)))).ToArray();

    private sealed class Profile : IDisposable
    {
        public string Root { get; } = Path.GetFullPath(Path.Combine("artifacts", "tests", "nomad-router", "unit-" + Guid.NewGuid().ToString("N")));
        public string Source => Path.Combine(Root, "primary");
        public string Target => Path.Combine(Root, "native");
        public string RouterSource => Path.Combine(Source, "storage", "lxmf");
        public Identity Own { get; } = Identity.Generate();
        public string SourceRatchets => Path.Combine(RouterSource, "ratchets", Convert.ToHexStringLower(LxMessage.DeliveryDestinationHash(Own)) + ".ratchets");
        public string NativeRatchets => Path.Combine(Target, "storage", "lxmf", "ratchets", Path.GetFileName(SourceRatchets));
        public byte[] RatchetHash { get; }
        public LxmRouterOptions Options => new() { StoragePath = Path.Combine(Target, "storage"), EnableRatchets = true };
        public Profile()
        {
            Directory.CreateDirectory(Path.GetDirectoryName(SourceRatchets)!);
            var secret = Own.ExportPrivateKey();
            try { File.WriteAllBytes(Path.Combine(Source, "storage", "identity"), secret); }
            finally { CryptographicOperations.ZeroMemory(secret); }
            File.WriteAllText(Path.Combine(Source, "config"), "[client]\nenable_client=Yes\nannounce_at_start=No\nperiodic_lxmf_sync=No\n[node]\nenable_node=No\n");
            File.WriteAllBytes(Path.Combine(Source, "storage", "peersettings"),
                MsgPack.Pack(new Dictionary<object, object?> { ["display_name"] = "Router migration synthetic user" }));
            using var fixture = Fixture();
            foreach (var file in fixture.RootElement.GetProperty("publicFilesHex").EnumerateObject())
                File.WriteAllBytes(Path.Combine(RouterSource, file.Name), Convert.FromHexString(file.Value.GetString()!));
            var key = RandomNumberGenerator.GetBytes(32);
            var encoded = SignedDestinationRatchetFile.Encode(Own, [key]);
            RatchetHash = SHA256.HashData(key);
            try { File.WriteAllBytes(SourceRatchets, encoded); }
            finally { CryptographicOperations.ZeroMemory(key); CryptographicOperations.ZeroMemory(encoded); }
        }
        public Task<NomadNetProfileImportReport> ImportAsync(CancellationToken token = default) =>
            NomadNetProfileImport.ImportAsync(Source, Target, Path.Combine(Root, "rns"), token);
        public void AssertNotPublished()
        {
            Assert.False(Directory.Exists(Target));
            Assert.Empty(Directory.GetDirectories(Root, "native.profile-import-*"));
        }
        public void Dispose()
        {
            Own.Dispose();
            if (Directory.Exists(Root)) Directory.Delete(Root, true);
        }
    }
}
